    // ── أوصاف: التراكب والمقاطع والصوت ──
    "Clips the last 30 seconds to 2 minutes of your stream, depending on your settings.": "يلتقط آخر 30 ثانية إلى دقيقتين من بثّك، حسب إعداداتك.",
    "Allow anyone in a shared voice channel to join my game without sending a request. This feature only works in non-Community enabled servers.": "السماح لأي أحد في قناة صوتية مشتركة بالانضمام للعبتي دون إرسال طلب. تعمل هذه الميزة فقط في الخوادم غير المجتمعية.",
    "Allows areas of the overlay (ie notifications) to be clickable while the overlay is locked.": "يسمح بأن تكون مناطق التراكب (كالإشعارات) قابلة للنقر أثناء قفل التراكب.",
    "Hold to open the soundboard at your mouse's location while in the game overlay.": "اضغط مطوّلاً لفتح لوحة الأصوات عند موضع الفأرة أثناء تراكب اللعبة.",
    "Open the soundboard at your mouse's location while in the game overlay.": "فتح لوحة الأصوات عند موضع الفأرة أثناء تراكب اللعبة.",
    "Lets you know when you are able to stream a game when the overlay first opens.": "يُعلمك متى يمكنك بثّ لعبة عند فتح التراكب أول مرّة.",
    "Shows a notice every time the overlay opens to let you know that the overlay is now active.": "يُظهر إشعاراً كلّما فُتح التراكب لإعلامك بأنه نشط الآن.",
    "Shows friends who are currently playing, or have recently played the game you're currently playing.": "يُظهر الأصدقاء الذين يلعبون حالياً، أو لعبوا مؤخّراً، اللعبة التي تلعبها.",
    "Legacy Overlay available for all supported games.": "التراكب القديم متاح لكل الألعاب المدعومة.",
    "If Overlay isn't working as expected, let us know so we can fix it.": "إن لم يعمل التراكب كما هو متوقّع، أخبرنا لنُصلحه.",
    "These shortcuts work when focused on a draggable item": "تعمل هذه الاختصارات عند التركيز على عنصر قابل للسحب",
    "These shortcuts work when focused on a message.": "تعمل هذه الاختصارات عند التركيز على رسالة.",
    "This action doesn't do anything! Please choose one from the drop down.": "هذا الإجراء لا يفعل شيئاً! اختر واحداً من القائمة المنسدلة.",
    "Toggle to start/stop streaming in your current voice channel. Streams can only be started with this keybind if Discord recognizes the game you are currently playing.": "بدّل لبدء/إيقاف البثّ في قناتك الصوتية الحالية. لا يمكن بدء البثّ بهذا الاختصار إلا إذا تعرّف ديسكورد على اللعبة التي تلعبها.",
    "Lower the volume of other applications by this percent when someone is speaking.\nSet to 0% to completely disable global attenuation.": "خفّض مستوى التطبيقات الأخرى بهذه النسبة عند تحدّث أحد.\nاضبطه على 0% لتعطيل التخفيف العام كلياً.",
    "Hints to your router that the packets Discord is transmitting are high priority.\nSome routers or internet service providers may misbehave when this is set.": "يُلمّح لموجّهك أن حزم ديسكورد ذات أولوية عالية.\nقد تسيء بعض الموجّهات أو مزوّدي الخدمة التصرّف عند تفعيله.",

