    "Developer Mode exposes context menu items helpful for people writing apps using the Discord API.": "وضع المطوّر يُظهر عناصر قائمة السياق المفيدة لمن يكتبون تطبيقات باستخدام واجهة برمجة ديسكورد.",
    "Improves Discord's functionality across games and apps. Helps ensure things like keybinds and other features work reliably.": "يُحسّن وظائف ديسكورد عبر الألعاب والتطبيقات. ويساعد على ضمان عمل أشياء كالاختصارات وغيرها بموثوقية.",
    "Some information about games (such as genre or cover art) is provided by IGDB.": "بعض المعلومات عن الألعاب (كالنوع أو صورة الغلاف) مُقدَّمة من IGDB.",
    "Enable display name styles — including font, effect, and color — across Discord.": "تفعيل أنماط اسم العرض — بما فيها الخطّ والتأثير واللون — عبر ديسكورد.",
