    "Enabling this will show the members page in the channel list, allowing you to quickly see who's recently joined your server, and find any users flagged for unusual activity.": "تفعيل هذا سيُظهر صفحة الأعضاء في قائمة القنوات، ما يتيح لك رؤية من انضمّ مؤخراً إلى خادمك بسرعة، والعثور على أي مستخدمين مُعلَّمين بنشاط غير معتاد.",
    "Engaged in suspected spam activity": "منخرط في نشاط سخام مُشتبه به",
