    // الاشتراكات و Nitro والفوترة
    ". Nitro and Server Boost are auto-recurring subscriptions. You authorize Discord to immediately charge the payment method provided at $2.99 and to continue to do so automatically monthly until you cancel. Prices subject to change with notice to you. You may cancel anytime.": ". Nitro و Server Boost اشتراكان متجدّدان تلقائياً. أنت تُفوّض Discord بخصم $2.99 فوراً من وسيلة الدفع المُقدّمة، والاستمرار بذلك تلقائياً شهرياً حتى تُلغي. الأسعار عرضة للتغيير بإشعارك. يمكنك الإلغاء في أي وقت.",
    "(Pending Cancellation)": "(قيد الإلغاء)",
    "Charging up...": "جارٍ الشحن...",
    "Credits are stored here and automatically applied. If you have Nitro, credits activate between billing cycles, and your paid subscription will renew once credits are used.": "تُخزَّن الأرصدة هنا وتُطبَّق تلقائياً. إن كان لديك Nitro، تُفعَّل الأرصدة بين دورات الفوترة، ويُجدَّد اشتراكك المدفوع بمجرّد استخدام الأرصدة.",
    "Credits are stored here and automatically applied. If you have Nitro, credits activate between billing cycles, and your paid subscription will renew once credits are used. {0}.": "تُخزَّن الأرصدة هنا وتُطبَّق تلقائياً. إن كان لديك Nitro، تُفعَّل الأرصدة بين دورات الفوترة، ويُجدَّد اشتراكك المدفوع بمجرّد استخدام الأرصدة. {0}.",
    "All credits will activate on": "ستُفعَّل كل الأرصدة في",
