    "Stage Channel Permissions": "أذونات قناة المسرح",
    "Allow requests to speak in Stage channels. Stage moderators manually approve or deny each request.": "السماح بطلبات التحدّث في قنوات المسرح. يوافق مشرفو المسرح على كل طلب أو يرفضونه يدوياً.",
    "Allows members to view Server Insights, which shows data on community growth, engagement, and more. This will allow them to see certain data about channel activity, even for channels they cannot access.": "يسمح للأعضاء بعرض إحصاءات الخادم، التي تُظهر بيانات عن نمو المجتمع والتفاعل وغيرها. سيتيح لهم رؤية بيانات معيّنة عن نشاط القنوات، حتى القنوات التي لا يمكنهم الوصول إليها.",
    "Adding connection or app requirements to an existing role is only possible if the role has no members. Consider creating a new role instead.": "إضافة متطلّبات اتصال أو تطبيق إلى رتبة موجودة ممكنة فقط إن لم يكن للرتبة أعضاء. ففكّر في إنشاء رتبة جديدة بدلاً من ذلك.",
    "Linking a connection or app requires members to connect their accounts before being added to the role.": "ربط اتصال أو تطبيق يتطلّب من الأعضاء ربط حساباتهم قبل إضافتهم إلى الرتبة.",
    "Linking a connection or app requires members to connect their accounts before being added to the role. {0}.": "ربط اتصال أو تطبيق يتطلّب من الأعضاء ربط حساباتهم قبل إضافتهم إلى الرتبة. {0}.",
    "Bans by default are by account and IP.\nA user can circumvent an IP ban by using a proxy.\nBan circumvention can be made very hard by enabling phone verification in": "الحظر افتراضياً يكون بالحساب وعنوان IP.\nيمكن للمستخدم تجاوز حظر IP باستخدام وسيط (proxy).\nيمكن جعل تجاوز الحظر صعباً جداً بتفعيل التحقّق بالهاتف في",
    "Bans by default are by account and IP.\nA user can circumvent an IP ban by using a proxy.\nBan circumvention can be made very hard by enabling phone verification in {0}.": "الحظر افتراضياً يكون بالحساب وعنوان IP.\nيمكن للمستخدم تجاوز حظر IP باستخدام وسيط (proxy).\nيمكن جعل تجاوز الحظر صعباً جداً بتفعيل التحقّق بالهاتف في {0}.",
