    "Yes, Boosts used for additional perks are dedicated specifically to those perks and don't count toward your server's level progression. Similarly, Boosts allocated to your server level can't be used for additional perks. You'll need separate Boosts for each - so if you want Enhanced Role Styles, you need 3 Boosts just for that perk, plus whatever Boosts you want to maintain your current server level.": "نعم، التعزيزات المُستخدَمة للمزايا الإضافية مُخصّصة لتلك المزايا تحديداً ولا تُحتسَب ضمن تقدّم مستوى خادمك. وبالمثل، التعزيزات المُخصّصة لمستوى خادمك لا يمكن استخدامها للمزايا الإضافية. ستحتاج تعزيزات منفصلة لكلٍّ منها — فإذا أردت أنماط الرتب المحسّنة، ستحتاج 3 تعزيزات لتلك الميزة فقط، بالإضافة إلى ما تريده من تعزيزات للحفاظ على مستوى خادمك الحالي.",
