    "Filter DMs from unknown users to Message Requests Inbox. Members must approve the request before they are able to respond.": "تصفية الرسائل الخاصة من المستخدمين المجهولين إلى صندوق طلبات الرسائل. على الأعضاء الموافقة على الطلب قبل أن يتمكّنوا من الردّ.",
