    "Give your mods a break while keeping your server safe! Set up filters to moderate content and automate a custom response when they're found, and AutoMod will make it happen.": "أرِح مشرفيك مع إبقاء خادمك آمناً! أعدّ مرشّحات لمراقبة المحتوى وأتمتة ردّ مخصّص عند العثور عليه، وسيتولّى AutoMod تنفيذ ذلك.",
