    "Monitor messages, Forum posts, and threads for potentially spammy content or activity. (Support for English only)": "راقب الرسائل ومنشورات المنتدى والمواضيع بحثاً عن محتوى أو نشاط محتمَل الشبه بالسبام. (الدعم للإنجليزية فقط)",
    "Prevents a member from using text, voice, or other interactions.": "يمنع العضو من استخدام النصّ أو الصوت أو التفاعلات الأخرى.",
    "Receive notifications for DM or join activity that exceeds usual numbers for your server. Each notification will contain information about the activity, including time period and approximate number of joins or DMs.": "تلقَّ إشعارات عن نشاط الرسائل الخاصة أو الانضمام الذي يتجاوز الأعداد المعتادة لخادمك. سيحوي كل إشعار معلومات عن النشاط، بما في ذلك الفترة الزمنية والعدد التقريبي للانضمامات أو الرسائل الخاصة.",
    "Remove risky permissions from @everyone": "إزالة الصلاحيات الخطرة من @everyone",
    "Send suspicious DMs to a separate Spam Inbox. Members can send a scam report or move it back to Inbox.": "أرسل الرسائل الخاصة المشبوهة إلى صندوق سبام منفصل. يمكن للأعضاء إرسال بلاغ احتيال أو إعادتها إلى صندوق الوارد.",
    "Sends an alert containing the flagged message to a chosen channel.": "يرسل تنبيهاً يحوي الرسالة المُعلَّمة إلى قناة مختارة.",
    "Warn members before they visit outbound links": "تحذير الأعضاء قبل زيارة الروابط الخارجية",
    "Moderators must have two-factor authentication enabled to ban, kick, or timeout members and delete messages.": "يجب أن يُفعّل المشرفون المصادقة الثنائية لحظر الأعضاء أو طردهم أو تعطيلهم مؤقتاً وحذف الرسائل.",
    "Only the server owner can change this setting if they have 2FA enabled.": "يمكن لمالك الخادم وحده تغيير هذا الإعداد إن كانت المصادقة الثنائية مُفعّلة لديه.",
    "This setting can only be changed by a server owner with 2FA enabled on their account.": "لا يمكن تغيير هذا الإعداد إلا من قِبَل مالك خادم لديه المصادقة الثنائية مُفعّلة في حسابه.",
    "This feature is on by default": "هذه الميزة مُفعّلة افتراضياً",
