    "Use the ** * ** character at the beginning or end of your keyword for partial matches within a word.": "استخدم الحرف ** * ** في بداية كلمتك المفتاحية أو نهايتها للمطابقات الجزئية داخل الكلمة.",
    // مرشّحات المحتوى والتكاملات
