    "Choose if server members can share image-based media detected by Discord's sensitive content filters. This setting will apply to channels that are not age-restricted. {0}": "اختر ما إذا كان بإمكان أعضاء الخادم مشاركة الوسائط الصورية التي تكتشفها مرشّحات المحتوى الحسّاس في Discord. ينطبق هذا الإعداد على القنوات غير المقيّدة بالعمر. {0}",
