    "Apply to be in": "تقدّم للانضمام إلى",
    "Apply to be in {0} so more people can find your server directly on Discord.": "تقدّم للانضمام إلى {0} ليتمكّن مزيد من الأشخاص من العثور على خادمك مباشرةً على Discord.",
    "so more people can find your server directly on Discord.": "ليتمكّن مزيد من الأشخاص من العثور على خادمك مباشرةً على Discord.",
    "Moderators must have two-factor authentication enabled to ban, kick, or timeout members and delete messages. Only the server owner can change this setting if they have 2FA enabled.": "يجب أن يُفعّل المشرفون المصادقة الثنائية لحظر الأعضاء أو طردهم أو فرض مهلة عليهم وحذف الرسائل. لا يمكن لغير مالك الخادم تغيير هذا الإعداد، وذلك إن كان قد فعّل المصادقة الثنائية.",
    "Must also be a member of this server for longer than {min} minutes.": "يجب أيضاً أن يكون عضواً في هذا الخادم لأكثر من {min} دقيقة.",
    "Must also be registered on Discord for longer than {min} minutes.": "يجب أيضاً أن يكون مسجّلاً في Discord لأكثر من {min} دقيقة.",
    "Must have a verified email on their Discord account.": "يجب أن يملك بريداً إلكترونياً موثّقاً في حساب Discord.",
    "Must have a verified phone on their Discord account.": "يجب أن يملك رقم هاتف موثّقاً في حساب Discord.",
    "Messages from server members without a role will be filtered for sensitive image-based media.": "ستُصفّى رسائل أعضاء الخادم الذين بلا رتبة بحثاً عن وسائط صورية حسّاسة.",
