    "You can't enable Apply from Profile if your server has “Private Profile” enabled. You can change this setting in the {0}.": "لا يمكنك تفعيل «التطبيق من الملف الشخصي» إذا كان خادمك يفعّل «الملف الشخصي الخاص». يمكنك تغيير هذا الإعداد في {0}.",
