    "There's a very small—and we mean small—chance you can get a secret ringtone when calling someone. Good luck!": "هناك فرصة ضئيلة جداً — ونعني ضئيلة — للحصول على نغمة رنين سرّية عند الاتصال بشخص. حظاً موفّقاً!",
    "Statistically speaking, the majority of Discord users believe that pineapple and pizza is the most cursed food combo. Thank our Polls feature launch for this Discord Fact™.": "إحصائياً، يعتقد غالبية مستخدمي ديسكورد أن الأناناس والبيتزا أسوأ مزيج طعام. اشكر إطلاق ميزة الاستطلاعات على هذه الحقيقة™.",
