    "Members will be restricted to creating one post per this interval, unless they have the Bypass Slowmode permission.": "سيُقيَّد الأعضاء بإنشاء منشور واحد كل هذه المدة، ما لم يملكوا إذن تجاوز الوضع البطيء.",
