    "Set the default layout view to a media-focused gallery or a text-focused list. Members will still be able to toggle between these options.": "اضبط التخطيط الافتراضي على معرض يركّز على الوسائط أو قائمة تركّز على النصّ. سيظلّ بإمكان الأعضاء التبديل بين الخيارين.",
    "Set the default sort order for new posts. Members will still be able to toggle between these options.": "اضبط ترتيب الفرز الافتراضي للمنشورات الجديدة. سيظلّ بإمكان الأعضاء التبديل بين الخيارين.",
    "Set the default tag matching behaviour. Members will still be able to toggle between these options.": "اضبط سلوك مطابقة الوسوم الافتراضي. سيظلّ بإمكان الأعضاء التبديل بين الخيارين.",
