    "By making a category private, only select members and roles will be able to view this category. Linked channels in this category will automatically match to this setting.": "بجعل الفئة خاصّة، لن يتمكّن من رؤية هذه الفئة إلا أعضاء ورتب محدَّدون. وستُطابق القنوات المرتبطة بهذه الفئة هذا الإعداد تلقائيّاً.",
