    "Discord doesn't have to be so black and white. Create your own custom theme to make Discord uniquely yours.": "ليس على ديسكورد أن يبقى بالأبيض والأسود. أنشئ سمتك الخاصة ليصير ديسكورد على ذوقك وحدك.",
