    "Get {totalSeats} memberships on one shared plan, and take your crew to the next level with {premiumGroupProductName}.": "احصل على {totalSeats} عضوية ضمن خطة مشتركة واحدة، وارتقِ بمجموعتك مع {premiumGroupProductName}.",
    "Keep the Orbs Coming": "واصِل جمع الـOrbs",
    "Unlock more Orbs with Nitro": "احصل على المزيد من الـOrbs مع Nitro",
    "Enjoy extra Orbs each month to spend in the Shop! Orbs unlock a few days after subscribing.": "استمتع بـOrbs إضافية كل شهر تُنفقها في المتجر! تُفتَح بعد أيام قليلة من الاشتراك.",
    "Grow your stash with monthly Orb drops and a 1.2x multiplier on Quest Rewards.": "نمِّ رصيدك بإسقاطات Orbs شهرية ومضاعِف 1.2 على مكافآت المهام.",
    "Turn Quest wins into mega wins with a 1.2x multiplier on Orb Rewards.": "حوِّل مكاسب المهام إلى مكاسب ضخمة بمضاعِف 1.2 على مكافآت الـOrbs.",
