    "What connected guardians can see": "ما يستطيع الأولياء المرتبطون رؤيته",
    "What guardians can manage": "ما يستطيع الأولياء إدارته",
    "What guardians will not see": "ما لن يراه الأولياء",
    "Guardians can set up safeguards to give their teens the best experience on Discord while being safe.": "يستطيع الأولياء ضبط وسائل حماية تمنح أبناءهم أفضل تجربة على ديسكورد مع بقائهم آمنين.",
    "Give your teen a break by choosing the hours and days when Discord won't be accessible.": "امنح ابنك استراحة باختيار الساعات والأيام التي لا يكون فيها ديسكورد متاحاً.",
    "Your guardian can schedule times when Discord won't be available. Use this time to take a break and recharge.": "يستطيع وليّك تحديد أوقات لا يكون فيها ديسكورد متاحاً. استغلّها للراحة واستعادة نشاطك.",
    "Set a monthly budget for your teen's Discord purchases, including shop items, gifting, and more. Does not include subscriptions.": "حدّد ميزانية شهرية لمشتريات ابنك في ديسكورد، وتشمل عناصر المتجر والإهداء وغيرها. لا تشمل الاشتراكات.",
    "Your guardian can set a monthly budget for your Discord purchases, including shop items, gifting, and more. Does not include subscriptions.": "يستطيع وليّك تحديد ميزانية شهرية لمشترياتك في ديسكورد، وتشمل عناصر المتجر والإهداء وغيرها. لا تشمل الاشتراكات.",
    "All gifts you received in the last week, including who sent them and how much they spent": "كل الهدايا التي استلمتها في الأسبوع الماضي، ومَن أرسلها وكم أنفق",
    "All gifts your teen received in the last week, including who sent them and how much they spent": "كل الهدايا التي استلمها ابنك في الأسبوع الماضي، ومَن أرسلها وكم أنفق",
    "All purchases you have made including Shop and subscriptions": "كل مشترياتك، وتشمل المتجر والاشتراكات",
    "Minutes spent in calls across direct messages group chats, and servers": "الدقائق التي قضيتها في المكالمات عبر الرسائل الخاصة والمجموعات والخوادم",
    "Includes servers you have recently created, joined, sent messages in, or participated in a voice and video call": "تشمل الخوادم التي أنشأتها أو انضممت إليها أو راسلت فيها أو شاركت فيها بمكالمة صوتية أو مرئية مؤخّراً",
    "Includes servers your teen has recently created, joined, sent messages in, or participated in a voice and video call": "تشمل الخوادم التي أنشأها ابنك أو انضمّ إليها أو راسل فيها أو شارك فيها بمكالمة صوتية أو مرئية مؤخّراً",
    "You will not see the contents of your teens' messages or calls.": "لن ترى محتوى رسائل أبنائك ولا مكالماتهم.",
